// València's road markings in the detailed city, generated by tools/build-markings.py from the Ajuntament de
// València's Senyalització horitzontal / Señalización horizontal (CC BY 4.0): every lane line, zebra crossing, bus and
// bike lane line, parking bay and no-parking line, rebuilt as strokes (a centre polyline, a width and a dash pattern)
// and filled polygons. Format (VLM2, gzipped) in the build script's header.
import { decodeMarkings } from './vlc-markings-decode.js';

// A missing or unreadable file leaves the streets unpainted rather than stopping the game.
async function load() {
  try {
    const response = await fetch(new URL('./vlc-markings.bin.gz', import.meta.url));
    if (!response.ok) throw new Error(`Marking data request failed: ${response.status}`);
    const body = new Uint8Array(await response.arrayBuffer());
    const data = body[0] === 0x1f && body[1] === 0x8b
      ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
      : body;
    return decodeMarkings(data);
  } catch (error) {
    console.error('[markings]', error);
    return { styles: [], strokes: [], polys: [] };
  }
}

export const REAL_MARKINGS = await load();
